CREATE OR REPLACE FUNCTION public.save_gunsan_bike(p_data jsonb, p_revision bigint)
 RETURNS SETOF gunsan_bike_datasets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare current_row public.gunsan_bike_datasets;
begin
 if auth.uid() is distinct from '11111111-1111-4111-8111-111111111111'::uuid then
 raise exception '편집 계정으로 로그인하세요.' using errcode = '42501';
 end if;
 if p_data->>'type' is distinct from 'FeatureCollection' or jsonb_typeof(p_data->'features') is distinct from 'array' then
 raise exception 'GeoJSON 형식이 올바르지 않습니다.';
 end if;
 perform pg_advisory_xact_lock(73194201);
 select * into current_row from public.gunsan_bike_datasets where id = 'gunsan_bike' for update;
 if coalesce(current_row.revision,0) <> p_revision then
 raise exception '다른 컴퓨터에서 먼저 저장했습니다. 현재 작업을 내보낸 뒤 최신 노선을 다시 불러오세요.' using errcode = '40001';
 end if;
 if current_row.id is not null then
 insert into public.gunsan_bike_history values (current_row.revision,current_row.data,current_row.updated_at,current_row.updated_by);
 end if;
 return query insert into public.gunsan_bike_datasets(id,data,revision,updated_at,updated_by)
 values ('gunsan_bike',p_data,p_revision+1,now(),auth.uid())
 on conflict(id) do update set data=excluded.data,revision=excluded.revision,updated_at=excluded.updated_at,updated_by=excluded.updated_by
 returning *;
end;
$function$
